///
/// `size`/`focus`/`screen_on` 都允许为 None:查询失败只表示"这一轮没读到",
/// **绝不**能被当成"尺寸变了" —— 否则一次 adb 抖动就会抬起玩家所有触点。
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct DeviceProbe {
    /// 当前触摸坐标空间(dumpsys window displays 的 cur=;失败回退 wm size)
    pub size: Option<(u32, u32)>,
    /// 当前焦点窗口(mCurrentFocus / mFocusedApp 的窗口名)
    pub focus: Option<String>,
    /// 屏幕是否亮着(dumpsys display 的 mScreenState=ON)
    pub screen_on: Option<bool>,
}

/// 一次设备侧巡检:坐标空间 + 焦点窗口 + 屏幕亮灭。
pub fn device_probe(serial: &str) -> DeviceProbe {
    let mut probe = DeviceProbe::default();
    if let Ok(out) = adb_cmd(Some(serial)).args(["shell","dumpsys","window","displays"]).output() {
        let text = String::from_utf8_lossy(&out.stdout);
        probe.size = parse_display_size(&text);
        probe.focus = parse_current_focus(&text);
    }
    if probe.size.is_none() {
        probe.size = screen_size(serial).ok();  // 回退
    }
    if let Ok(out) = adb_cmd(Some(serial)).args(["shell","dumpsys","display"]).output() {
        probe.screen_on = parse_screen_on(&String::from_utf8_lossy(&out.stdout));
    }
    probe
}
