pub fn device_probe(serial: &str) -> DeviceProbe {
    let mut p = DeviceProbe::default();
    // ① 一次 adb shell 里跑完三条查询(省两次进程创建;设备端本来就是同一批
    //    dumpsys)。用 ';' 串起来 —— adb shell 后面只跟一个参数时,整个字符串
    //    原样交给设备 shell。
    let out = adb_cmd(Some(serial))
        .args(["shell", "dumpsys window displays; dumpsys display"])
        .output();
    match out {
        Ok(o) => {
            let text = String::from_utf8_lossy(&o.stdout);
            p.size = parse_display_size(&text);
            p.focus = parse_current_focus(&text);
            p.screen_on = parse_screen_on(&text);
        }
        Err(_) => {}
    }
    if p.size.is_none() {
        // `dumpsys window displays` 那条路解析不出来(部分 ROM 的 cur= 格式不同)
        // ⇒ 回退到既有逻辑:再试一次 displays,再退 `wm size`。
