/// 启动一次设备巡检(工作线程 + channel;绝不在持锁时做 adb)。
///
/// 与 `refresh_display_space` 共用 `adb::device_probe` 里的取尺寸逻辑
/// (`dumpsys window displays`,失败回退 `wm size`)。
fn start_space_probe(&mut self) {
    if self.space_watch_rx.is_some() { return; }
    let serial = self.serial();
    if serial.is_empty() { return; }
    let (tx, rx) = channel();
    self.space_watch_rx = Some(rx);
    self.space_watch_last = Instant::now();
    std::thread::spawn(move || {
        let _ = tx.send(adb::device_probe(&serial));
    });
}
```

