#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct DeviceProbe {
    /// 当前触摸坐标空间(`dumpsys window displays` 的 `cur=WxH`;解析不到时
    /// 回退 `wm size`,此时 [`Self::size_is_display_space`] 为 false)。
    pub size: Option<(u32, u32)>,
    /// `size` 是不是真的来自 `dumpsys` 里的 `cur=`(即**当前方向**的坐标空间)。
    ///
    /// 回退值 `wm size` 是**物理分辨率、永远自然方向**:横屏设备上它与真实
    /// 坐标空间正好差 90°,拿它跟缓存比对必然误判"空间变了"。所以回退值只能
