/// 周期巡检的判定(纯函数):该不该走"更新坐标空间 + 抬起所有触点 + 失效锚点"。
///
/// 返回 true ⇔ **确定**当前触摸坐标空间与缓存不同。三条不动作的理由:
/// 没变 / 这一轮没查到 / 查到的只是回退的 `wm size`(自然方向,横屏下差 90°,
/// 拿它比对必然误报 —— 而误报会平白抬起玩家正按着的所有触点)。
fn space_change_detected(
    cached: (u32, u32),
    probed: Option<(u32, u32)>,
    probed_is_display_space: bool,
) -> bool {
    let Some((w, h)) = probed else {
        return false;
    };
    if w == 0 || h == 0 || !probed_is_display_space {
        return false;
    }
    (w, h) != cached
}

/// "值变了才说"的判定(纯函数):焦点窗口/屏幕状态这类遥测只在变化时写日志。
///
/// * `prev == None` → 第一次拿到值:说(否则日志里永远没有基线);
/// * `now  == None` → 这一轮没查到:不说(查不到不是"变了");
/// * 两边都有且不同 → 说。
fn telemetry_changed<T: PartialEq>(prev: Option<&T>, now: Option<&T>) -> bool {
    match now {
        None => false,
        Some(v) => prev != Some(v),
    }
}
