```rust
    /// 周期性坐标空间巡检:到点就在**工作线程**上跑一次设备查询,结果经 channel 回界面。
    ///
    /// 与 `refresh_display_space` 的区别(两者都要留着):
    ///   * `refresh_display_space` 是"某个事件刚发生,补一次"(开打 / 空闲恢复),
    ///     在途时会被 `self.space_rx.is_some()` 挡住,也可能被[取消坐标刷新]清掉;
    ///   * 这一条**只认定时器**,与输入无关 —— 正是"玩家碰了一下手机、之后
    ///     一个键都没按"那种场景里唯一还会跑的重查。
    fn maybe_space_watch(&mut self) {
        if self.space_watch_rx.is_some() {
            return;
        }
        if self.space_watch_last.elapsed() < SPACE_WATCH_INTERVAL {
            return;
        }
        // 只在"映射开着且控制通道在线"时查:这两个条件不成立时坐标空间没人用,
        // 白查一轮只会平白多一次 adb(而且离线时 adb 还可能超时)。
        // 不推进计时器的原因:等条件恢复时应当**立刻**补一轮,而不是再等 2 秒。
        let (enabled, online) = {
            let g = lock_shared(&self.shared);
            (g.enabled, g.control.is_some())
        };
        if !enabled || !online {
            return;
        }
        self.start_space_watch();
    }

    /// 起一轮后台巡检(绝不在持锁时做 adb:这里只取序列号,adb 在工作线程里跑)
    fn start_space_watch(&mut self) {
        if self.space_watch_rx.is_some() {
            return;
        }
        let serial = self.serial();
        if serial.is_empty() {
            return;
        }
        let (tx, rx) = channel();
        self.space_watch_rx = Some(rx);
        self.space_watch_last = Instant::now();
        std::thread::spawn(move || {
            let _ = tx.send(adb::device_probe(&serial));
        });
    }

    /// 回收周期巡检的结果(每帧看一眼,不阻塞)
    fn poll_space_watch(&mut self) {
        let Some(rx) = self.space_watch_rx.as_ref() else {
            return;
        };
        match rx.try_recv() {
            Ok(probe) => {
                self.space_watch_rx = None;
                self.space_checked_at = Some(Instant::now());
                self.apply_device_probe(&probe);
            }
            Err(std::sync::mpsc::TryRecvError::Empty) => {}
            // 工作线程 panic / 通道断:清掉在途状态,下一轮重新起(否则永远不再查)
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                self.space_watch_rx = None;
            }
        }
    }
