```rust
/// 从 `dumpsys display` 里取"屏幕亮着吗"。
///
/// 各 Android 版本关键字不同:优先 `mScreenState=`(DisplayContent),
/// 退而用 `mGlobalDisplayState=`。只认 ON/OFF 两种明确取值 —— DOZE/UNKNOWN
/// 之类一律返回 None("宁可不报,也不把不确定说成灭屏")。
fn parse_screen_on(text: &str) -> Option<bool> {
    for key in ["mScreenState=", "mGlobalDisplayState="] {
        let Some(rest) = text.split_once(key).map(|(_, r)| r) else {
            continue;
        };
        let token: String = rest
            .trim_start()
            .chars()
            .take_while(|c| c.is_ascii_uppercase() || *c == '_')
            .collect();
        match token.as_str() {
            "ON" => return Some(true),
            "OFF" => return Some(false),
            _ => continue,
        }
    }
    None
}
```
